from pathlib import Path
from bs4 import BeautifulSoup
import base64,html,json,re,shutil
root=Path('/home/user')
path=root/'UK_Junior_Data_Analyst_Roadmap_Eastbourne.html'
old=BeautifulSoup((root/'reference/roadmap_v3_backup.html').read_text() if (root/'reference/roadmap_v3_backup.html').exists() else path.read_text(),'html.parser')
css=old.style.string
# Retain an editable snapshot and a record for migrating old ticks.
if not (root/'reference/roadmap_v3_backup.html').exists():shutil.copy(path,root/'reference/roadmap_v3_backup.html')
original=[x.get_text(' ',strip=True) for x in old.select('.check-item')]
def esc(s):return html.escape(str(s))
art={'hero':27,'goku':77,'lee':80,'solo':83,'naruto':246,'mha':480,'levi':804}
assets={k:'data:image/png;base64,'+base64.b64encode((root/f'reference/image_{v}.png').read_bytes()).decode() for k,v in art.items()}
def img(k,alt='',cls=''):return f'<img class="{cls}" src="{assets[k]}" alt="{esc(alt or k)}">'
def link(u,t):return f'<a href="{esc(u)}" target="_blank" rel="noopener noreferrer">{t} ↗</a>'
def head(k,t,p=''):return f'<div class="section-title"><div class="kicker">{k}</div><h2>{t}</h2><p>{p}</p></div>'
def section(id,k,t,p,body):return f'<section id="{id}"><div class="container">{head(k,t,p)}{body}</div></section>'
def poster(key,eyebrow,quote,text):return f'<div class="container"><aside class="quote-poster exact-poster">{img(key,eyebrow+" — original artwork extracted from your reference PDF")}<div class="text"><div class="eyebrow">{eyebrow}</div><h3>{quote}</h3><p>{text}</p></div></aside></div>'
E=('https://www.youtube.com/watch?v=pCJ15nGFgVg','Excel for Data Analytics — Full Course','Luke Barousse · ~11h · English · watch selected chapters')
S=('https://www.youtube.com/watch?v=HXV3zeQKqGY','SQL Tutorial — Full Database Course for Beginners','freeCodeCamp / Mike Dane · ~4h20 · English · MySQL syntax')
P=('https://www.youtube.com/watch?v=FwjaHCVNBWA','Power BI for Data Analytics — Full Course','Luke Barousse · ~8h25 · English')
Y=('https://www.youtube.com/watch?v=wUSDVGivd-8','Python for Data Analytics — Full Course','Luke Barousse · ~11h · English · select relevant chapters')
# Hours are the entire learning/building budget, not just video time: 28 x 12 = 336.
arcs=[
 dict(id='setup',n='01',name='Academy Arc',title='Setup, workflow & proof of work',weeks='1',hours=12,boss='A working toolkit, a public learning-log repository and one short analysis of a clean sample CSV.',intro='Start where you are: Excel experience and early SQL practice. This is a diagnostic and setup week, not a restart from zero.',resources=[('https://docs.github.com/en/get-started/start-your-journey/hello-world','GitHub Hello World','Official guide · free'),('https://learn.microsoft.com/en-us/power-bi/fundamentals/desktop-get-the-desktop','Get Power BI Desktop','Official Windows requirements & installation')],items=['Check your device: Power BI Desktop requires Windows; arrange Windows access if using a Mac.','Set up Excel or Microsoft 365 access; identify which Power Query features your version supports.','Install MySQL Community + Workbench, or use a browser SQL sandbox while setting up.','Create folders: raw-data, cleaned-data, sql, notebooks, reports and screenshots.','Create GitHub profile + learning-log repository; upload a README and a sample SQL file.','Learn Git status, add, commit, pull and push, or use GitHub’s web upload first.','Set a repeatable 12-hour weekly schedule around your actual rota.','Record your baseline: one PivotTable, one SELECT query and a 60-second explanation.','Use only public or synthetic data; never upload Lidl/customer/colleague data.','Write one analysis question with a metric, time period and intended reader.'],rule='If setup takes more than a session, use browser tools and keep practising. Tool installation is not the boss.'),
 dict(id='excel',n='02',name='Foundation Arc',title='Excel Pro & Power Query',weeks='2–4',hours=36,boss='Project 1: a refreshable retail workbook with raw/clean tabs, PivotTables and a one-page recommendation.',intro='Build on what you already know. Spend less time watching familiar material and more time explaining how you checked the result.',resources=[E,('https://support.microsoft.com/en-us/excel','Excel help & learning','Microsoft · reference')],items=['Clean like a pro: Duplicates, TRIM, flash fill','Formulas: IF, SUMIFS, TEXT/DATE','Lookups: VLOOKUP → XLOOKUP → INDEX/MATCH','PivotTables: Group by month, slicers, PivotChart','Power Query: Unpivot, merge, refresh','Dashboard: 1 interactive dashboard answering a business Q','Use Excel Tables, structured references and consistent data types.','Handle blanks, errors and dates with UK locale; distinguish missing values from zero.','Check XLOOKUP exact matches and unmatched keys; explain one-to-many lookup limits.','Calculate revenue, units, average basket and percentage change with explicit definitions.','Reconcile row counts and sales totals before and after cleaning.','Write three findings and one limitation; label synthetic data clearly.','Close the tutorial and rebuild your main PivotTable without help.','Export a readable dashboard PDF and document refresh steps.'],rule='Your boss test: someone else can replace the CSV and refresh the report without calling you.'),
 dict(id='sql',n='03',name='Chakra Control Arc',title='SQL for reliable answers',weeks='5–8',hours=48,boss='Project 2: a small retail database, 30 documented queries and a 30-minute closed-book SQL test.',intro='Use SQL to retrieve, combine and validate data. Practise the reasoning behind the query, not just the syntax.',resources=[S,('https://sqlbolt.com/','SQLBolt interactive lessons','Free · beginner practice'),('https://datalemur.com/sql-tutorial','SQL interview tutorial','DataLemur · fundamentals & patterns')],items=['Foundations: SELECT, WHERE, ORDER BY, NULLs','Aggregations: COUNT/SUM/AVG, GROUP BY, HAVING, CASE','JOINs: INNER/LEFT/FULL/UNION — understand preserved rows','Window: ROW_NUMBER, RANK, LAG/LEAD, PARTITION BY','Project: 10 queries to GitHub (retail or Northwind sample)','Understand primary/foreign keys, row grain and duplicate keys.','Filter dates safely with half-open intervals and explicit date formats.','Use IS NULL, COALESCE and NULLIF; explain COUNT(*) vs COUNT(column).','Demonstrate how a one-to-many join can inflate totals.','Write and explain a subquery and a CTE solving the same problem.','Find top products per category with a ranking window.','Calculate month-on-month change with LAG and handle missing months.','Find unmatched rows with LEFT JOIN + IS NULL or NOT EXISTS.','Explain WHERE vs HAVING; UNION vs UNION ALL.','Save 30 queries with questions, expected outputs and reconciliation checks.','Complete a timed test without copying; review mistakes the following day.'],rule='MySQL has no native FULL OUTER JOIN. Learn the concept and a UNION-based workaround; do not mix dialects silently.'),
 dict(id='pbi',n='04',name='Power-up Arc',title='Power BI, modelling & DAX',weeks='9–13',hours=60,boss='Project 3: a retail performance dashboard with a star schema, validated measures and a 3-minute demo.',intro='The hero skill is not adding charts. It is producing trustworthy measures and a page that helps a manager make one decision.',resources=[P,('https://learn.microsoft.com/en-us/power-bi/guidance/star-schema','Star schema guidance','Microsoft · official'),('https://learn.microsoft.com/en-us/dax/','DAX reference','Microsoft · official')],items=['Get Data: Power Query clean/unpivot','Model: Star schema, date table','DAX: SUM, DIVIDE, CALCULATE and filter context','Visuals: KPI cards, slicers, drill-through and accessible labels','Publish: Understand Service, sharing and refresh limitations','Portfolio: Retail dashboard + README + screenshots','Build fact sales and product/date/store dimensions with unique keys.','Use one-to-many relationships and explain filter direction.','Distinguish measures, calculated columns and Power Query steps.','Create a complete date table and consistent time intelligence measures.','Validate at least five KPI totals against Excel or SQL.','Show prior-period comparison only when date coverage is comparable.','Add clear units, source date, metric definitions and caveats.','Test slicers, drill-through, blank values and zero denominators.','Understand that Publish to web is public: only use non-sensitive public/synthetic data.','Provide PDF/screenshots + demo if you cannot share a live report.','Start a small number of targeted applications once Projects 1–3 are explainable.'],rule='Power BI Desktop authoring is free; some sharing and refresh options need licences. A paid subscription is not a prerequisite for portfolio evidence.'),
 dict(id='stats',n='05',name='Analyst Thinking Arc',title='Statistics, quality & storytelling',weeks='14–15',hours=24,boss='A one-page decision brief: one question, three checked findings, a recommendation and limitations.',intro='Use these ideas throughout every project; these two weeks consolidate them. This is analytics, not a machine-learning detour.',resources=[('https://www.khanacademy.org/math/statistics-probability','Statistics & probability','Khan Academy · free · selected topics'),('https://www.ons.gov.uk/','UK official statistics','ONS · metadata and methodology practice')],items=['Statistics: Mean, median, standard deviation and outliers','Correlation: Correlation ≠ causation; confounding','Story: Question → evidence → recommendation → limitation','Choose an appropriate denominator and avoid averaging averages.','Distinguish percentage change from percentage-point change.','Recognise sampling bias, selection bias and small sample problems.','Explain confidence intervals and uncertainty in plain English.','Describe a basic A/B test, control group and random assignment.','Check whether seasonality, missing periods or population changes affect comparisons.','Use bar/line charts appropriately and avoid misleading axis scales.','Define a KPI with unit, grain, owner, period and source.','Practise a 90-second explanation for a non-technical manager.'],rule='Never tick a finding until you can say what would make it wrong.'),
 dict(id='python',n='06',name='Automation Arc',title='Python, pandas & reproducibility',weeks='16–19',hours=48,boss='Project 4: a reproducible public-data analysis and a script that turns a raw CSV into a checked summary report.',intro='Add Python after Excel, SQL and Power BI. Do not delay suitable applications because you have not finished a Python playlist.',resources=[Y,('https://pandas.pydata.org/docs/getting_started/intro_tutorials/','pandas introductory tutorials','Official · free'),('https://docs.python.org/3/tutorial/','Python tutorial','Official · reference')],items=['Python: Variables, lists, dictionaries, loops and functions','pandas: Read CSV, inspect, filter and select','Clean: Missing values, duplicates and data types','Analyse: groupby, merge, pivot_table','Visualise: Matplotlib or Seaborn with readable labels','Project: Notebook + README + reproducible outputs','Create a virtual environment and record package requirements.','Parse dates explicitly; inspect UK/US date ambiguity.','Validate merge keys and check row counts before/after joins.','Write reusable functions for load, clean, validate and export.','Use assertions for totals, unique keys and non-negative values where appropriate.','Export clean CSV + an Excel summary without overwriting raw files.','Re-run from a clean environment or a fresh Colab session.','Keep secrets and personal data out of notebooks and version control.'],rule='One working automation is worth more than ten copied notebooks. Measure runtime or manual steps honestly; do not invent hours saved.'),
 dict(id='capstone',n='07',name='Final Boss Arc',title='An end-to-end analytics capstone',weeks='20–23',hours=48,boss='Project 5: an East Sussex public-data brief connecting SQL, a checked dataset and a Power BI dashboard, with a 5-minute walkthrough.',intro='Combine skills you already learned. Choose a question you can defend, rather than adding more tools.',resources=[('https://www.ons.gov.uk/','ONS datasets','Official public data · select a manageable CSV'),('https://data.eastsussex.gov.uk/','East Sussex in Figures','Local statistics & metadata'),('https://www.data.gov.uk/','Find open data','UK data catalogue')],items=['Choose one question: how has a selected local indicator changed over time?','Record source URL, download date, licence, geography and definitions.','Write a data dictionary and identify the grain of every table.','Keep immutable raw files and scripted cleaning steps.','Use SQL to answer at least eight meaningful questions.','Cross-check dashboard totals against SQL and an independent Excel calculation.','Explain missing data, boundary changes and incomparable time periods.','Create a concise dashboard with context, clear units and accessible colours.','Write a one-page insight brief, separating evidence from assumptions.','Document setup, refresh steps and known limitations in the README.','Record a 3–5 minute walkthrough: question, data, checks, insight, action.','Ask someone to reproduce one number and incorporate their feedback.','Polish your best three projects; keep two smaller ones as supporting evidence.'],rule='A reproducible analysis with caveats beats an attractive dashboard with unexplained numbers.'),
 dict(id='interview',n='08',name='Boss Dialogue Arc',title='SQL tests & interview confidence',weeks='24–25',hours=24,boss='Two timed SQL mocks, one Excel task, one dashboard critique and four truthful STAR stories.',intro='Build this habit earlier with short weekly practice. These weeks focus on presenting evidence clearly under time pressure.',resources=[('https://datalemur.com/questions','SQL interview questions','Practice · some questions may require an account'),('https://www.hackerrank.com/domains/sql','HackerRank SQL','Practice · free account')],items=['Explain a LEFT JOIN and demonstrate duplicate-row inflation aloud.','Complete two 30-minute SQL mocks and revisit every error.','Complete an Excel clean → lookup → pivot task from a fresh file.','Explain row context, filter context and CALCULATE using your report.','Present your flagship project in five minutes without reading notes.','Prepare a truthful 60-second Lidl → analytics career-change story.','Write four STAR stories: quality, teamwork, prioritisation and difficult customer.','State limitations and what you would investigate next.','Practise asking clarifying questions before starting a take-home task.','Prepare questions on data quality, onboarding, tools and success measures.','Rehearse a salary conversation using the advert’s range and role scope.'],rule='A gap is not a failure: explain what you know, what you would check and how you would test it.'),
 dict(id='jobs',n='09',name='Endgame Arc',title='Applications, referrals & feedback',weeks='26–28',hours=36,boss='A sustainable weekly pipeline, tailored CV and project links; iterate on real feedback rather than waiting for perfection.',intro='Applications can begin in week 13. Weeks 26–28 are a focused search sprint, not a promise that an offer arrives on a deadline.',resources=[('https://www.jobs.nhs.uk/','NHS Jobs','Search analyst, information analyst, reporting'),('https://www.civilservicejobs.service.gov.uk/','Civil Service Jobs','Check essential criteria and application format'),('https://www.reed.co.uk/jobs/junior-data-analyst-jobs-in-eastbourne','Reed: Eastbourne search','Use wider geography and related role titles too')],items=['Set alerts for Junior Data Analyst, MI Analyst, Reporting Analyst and BI Assistant.','Search Eastbourne, Lewes, Brighton/Hove and hybrid roles with a realistic commute.','Make a shortlist of ten employers; confirm vacancies on their own careers pages.','Write an ATS-readable CV with Excel, SQL, Power BI and project links near the top.','Only describe yourself as ex-Lidl if you have actually left; otherwise list your current role.','Apply to around five well-matched roles per week when available; adjust to supply and rota.','Send two personalised networking/referral messages per week without spamming.','Track date, criteria, CV version, follow-up, outcome and feedback.','Follow up once when appropriate and respect no-contact instructions.','After 15–20 matched applications without screens, review CV, eligibility and targeting.','Practise weekly while applying; do not restart a new bootcamp after each rejection.','Check salary, hours, location, employment status and any right-to-work/sponsorship conditions.','Keep learning and searching beyond week 28 if needed; extend the timeline, not the guilt.'],rule='No guaranteed conversion rate. Your targets are controllable actions; interview and offer outcomes are not.')
]
# Map existing progress indices to retained topics; old 34 tick states migrate only when meaningful.
legacy={}
for i,t in enumerate(original):
 clean=re.sub(r'\s+(CORE|PRO|PORTFOLIO)$','',t)
 for a in arcs:
  for j,item in enumerate(a['items']):
   if clean==item:legacy[str(i)]=f'{a["id"]}-{j}'
# Preserve all 23 prior ticks by their corresponding retained skill, not new list positions.
legacy.update({str(i):k for i,k in enumerate(['excel-0','excel-1','excel-2','excel-3','excel-4','excel-5','sql-0','sql-1','sql-2','sql-3','sql-4','pbi-0','pbi-1','pbi-2','pbi-3','pbi-5','python-6','python-1','python-4','python-5','stats-0','stats-2','stats-11'])})
count=sum(len(a['items']) for a in arcs)
