parts=[f'<!DOCTYPE html><html lang="en-GB"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Operation Data Analyst · Eastbourne Roadmap</title><style>{css}{extra_css}</style></head><body>']
parts.append('''<a href="#roadmap" class="skip">Skip to roadmap</a><div class="edition-bar"><span class="edition-pill"><span class="dot"></span>EASTBOURNE & SOUTH COAST EDITION · OCT 2026</span></div><nav aria-label="Main navigation"><div class="logo">OPERATION <span>DATA ANALYST</span></div><ul>'''+''.join(f'<li><a href="#{i}">{t}</a></li>' for i,t in [('market','Market'),('roadmap','Training'),('schedule','Schedule'),('projects','Projects'),('jobhunt','Job hunt'),('questions','Interviews'),('cheats','Cheat sheets')])+'''</ul></nav><div class="progress-top"><div id="progressBar"></div></div>''')
parts.append(f'''<header class="hero"><div class="hero-inner"><h1>From Lidl till to<br><span class="grad">Data Analyst desk.</span></h1><p class="lead">Your 28-week training arc for a junior data-analytics role, built around Lidl shifts and life in Eastbourne. Build on your Excel experience and early SQL practice, then turn Power BI, Python and clear thinking into evidence employers can inspect.</p><div class="hero-badges"><span class="badge-pill">28 weeks</span><span class="badge-pill">~12 hours / week</span><span class="badge-pill">Excel · SQL · Power BI</span><span class="badge-pill">Python + portfolio</span><span class="badge-pill">{count} checkpoints</span></div><div class="hero-progress"><div class="pct" id="heroPct">0%</div><div class="bar-wrap"><div class="bar-head"><span id="heroCount">0 / {count} checkpoints · E-Rank</span><span id="heroPct2">0%</span></div><div class="bar"><div class="fill" id="heroFill"></div></div></div><p class="foot">Ticks save in this browser, without jumping the page. Export a backup before changing browser or device.</p></div><div class="actions"><a class="btn primary" href="#roadmap">Start your training →</a><button onclick="printRoadmap()">Print / Save as PDF</button><a class="btn" href="TRACKER_URI" download="Eastbourne_Data_Analyst_Tracker.xlsx">Download Excel tracker</a></div><div class="hero-image">{img('hero','Original horizon / futuristic city artwork from the reference PDF')}<div class="overlay"><p>Eastbourne → Sussex opportunities → realistic hybrid or remote options</p></div></div><p class="estimate">Planning budget: 336 hours. A target timeline, not a job guarantee. If your rota changes, stretch the weeks rather than sacrificing sleep.</p></div></header>''')
arc_cards=[('goku','DRAGON BALL Z ARC','Work hard in silence.',"Goku didn’t unlock Super Saiyan by watching tutorials. One focused practice block today. Another tomorrow. Consistency is your power-up."),('lee','NARUTO ARC','Zero talent? Perfect.',"Rock Lee trained the fundamentals. You already have retail experience and Excel practice. Build on them—one checked query at a time."),('solo','SOLO LEVELING ARC','E-rank → S-rank.',"Day 1: a basic SELECT. Later: a dashboard you can defend. Level up through completed work, not finished playlists.")]
parts.append(section('training','TRAINING ARC','Real anime energy.','The same original images as your PDF. The training advice is now written for your analytics journey.','<div class="arc-grid">'+''.join(f'<article class="arc-card"><div class="arc-image">{img(k,t)}<span class="arc-label">{t.split(" ARC")[0]}</span></div><div class="arc-content"><div class="arc-subtitle">{t}</div><h4>{q}</h4><p>{s}</p></div></article>' for k,t,q,s in arc_cards)+'</div>'))
source_url='https://www.prospects.ac.uk/job-profiles/data-analyst/'
market=[('£28k–£32k','Typical starting salary','Prospects gives this UK starting range. It is not an Eastbourne-specific estimate or a guaranteed offer. [1]',source_url),('Excel + SQL','Your first foundations','Prospects lists spreadsheet/database skills and SQL among relevant analyst skills. Exact requirements vary by role. [1]',source_url),('Power BI / Tableau','Visualisation matters','Both appear in the Prospects skills profile. Power BI is the tool chosen for this plan; inspect local adverts before committing to another tool. [1]',source_url),('Python: selective','A later addition','Prospects describes Python or R as relevant for some roles. Build core reporting evidence first. [1]',source_url),('Explain the numbers','Communication is core','Prospects highlights data storytelling, quality, governance and analytical reasoning—not only coding. [1]',source_url),('Your own sample','Replace hype with evidence','Every two weeks, review ten relevant adverts and log tools, location, salary and eligibility. This is a recommended exercise, not a market statistic.','#jobhunt')]
marketbody='<div class="intel-grid">'+''.join(f'<article class="intel-card"><div class="stat-big">{t}</div><h3>{label}</h3><p>{desc}</p>{link(url,"[1] Prospects") if url==source_url else "<a href=\"#jobhunt\">Open search playbook →</a>"}</article>' for t,label,desc,url in market)+'</div>'
marketbody+='<div class="panel"><h3>So what does this mean for you?</h3><ul><li><b>Core path:</b> Excel → SQL → Power BI → credible projects. Practise statistics and communication throughout.</li><li><b>Retail is context, not invented analyst experience:</b> discuss stock, sales, waste and customer needs without claiming you analysed Lidl’s internal systems.</li><li><b>Broaden titles:</b> Reporting Analyst, MI Analyst, Information Analyst and BI Assistant can be relevant; read the duties, not just the title.</li><li><b>Do not wait for Python or a certificate:</b> apply when your evidence matches a role’s essential criteria. Respect degree, experience and eligibility requirements.</li></ul></div>'
tools=[('Excel + Power Query','Clean, reconcile and summarise operational data.','must','MUST','Weeks 2–4'),('SQL','Retrieve and join data; validate grain and totals.','must','MUST','Weeks 5–8'),('Power BI + DAX','Model data and explain decisions visually.','must','MUST','Weeks 9–13'),('Statistics + storytelling','Interpret uncertainty and communicate clearly.','must','MUST','Throughout; 14–15'),('GitHub + documentation','Make your work reproducible and easy to review.','should','SHOULD','Week 1 onward'),('Python + pandas','Automate analysis and repeatable reports.','should','SHOULD','Weeks 16–19'),('PL-300 certification','Optional structured validation after hands-on projects; check current fees.','bonus','BONUS','After core'),('Tableau / advanced cloud tools','Add only when repeated target adverts justify the switch.','later','LATER','After employable')]
marketbody+='<h3 style="margin-top:28px">Tool relevance for your target roles</h3><div class="table-wrap"><table><thead><tr><th>Tool / skill</th><th>Why it matters here</th><th>Priority</th><th>When</th></tr></thead><tbody>'+''.join(f'<tr><td>{a}</td><td>{b}</td><td><span class="pill {c}">{d}</span></td><td>{e}</td></tr>' for a,b,c,d,e in tools)+'</tbody></table></div><p class="muted">Priority and sequencing are recommendations for you, not measured percentages of UK adverts. No Business Analyst or full-stack curriculum is included.</p>'
parts.append(section('market','MARKET INTEL · UK','Train for the work, not the hype.','A grounded UK skills picture, with a local search strategy and no unsupported hiring percentages.',marketbody))
parts.append(poster('naruto','THE NINDŌ RULE','“I never go back on my word. That’s my ninja way.”','Use a rule, not a mood: avoid two unplanned skips in a row. After an exhausting shift, make the next session a ten-minute review. Planned rest and illness are not failures.'))
roadbody='<div class="panel"><div class="pill-menu">'+''.join(f'<a href="#card-{a["id"]}">{a["n"]} · {a["title"].split(" &")[0]}</a>' for a in arcs)+'</div><p class="muted" style="margin-top:15px">Nine seasons · 336 planned hours · five projects · '+str(count)+' checkpoints. Build before you tick. If you already know a topic, pass its practical test and move on.</p></div><div class="actions no-print"><span class="btn primary">Overall: <span id="overallProgress">0%</span></span><button onclick="expandAll()">Expand all</button><button onclick="collapseAll()">Collapse all</button><button onclick="exportProgress()">Export progress</button><button onclick="document.getElementById(\'importFile\').click()">Import progress</button><button onclick="resetProgress()">Reset</button><input type="file" id="importFile" accept="application/json" hidden></div><div id="checklist" class="topic-grid">'
for a in arcs:
 body=f'<p>{a["intro"]}</p><div class="boss"><b>Boss to defeat:</b> {a["boss"]}</div><div class="watch">WATCH / READ · ONE MAIN RESOURCE, THEN PRACTISE</div><div class="resources">'+''.join(f'<a class="resource" href="{esc(u)}" target="_blank" rel="noopener noreferrer">{t} ↗<small>{info}</small></a>' for u,t,info in a['resources'])+'</div>'
 body+=f'<div class="checklist" data-topic="{a["id"]}">'+''.join(f'<label class="check-item"><input type="checkbox" data-key="{a["id"]}-{j}"><span>{esc(item)}</span></label>' for j,item in enumerate(a['items']))+'</div>'
 body+=f'<div class="arc-footer"><b>Training rule:</b> {a["rule"]}</div>'
 roadbody+=f'<article class="topic-card {"open" if a["id"]=="setup" else ""}" id="card-{a["id"]}"><button class="arc-summary" type="button" aria-expanded="{"true" if a["id"]=="setup" else "false"}" aria-controls="body-{a["id"]}" onclick="toggleArc(this)"><span class="number">{a["n"]}</span><span class="title"><span class="kicker">{a["name"]} · WEEK {a["weeks"]}</span><h3>{a["title"]}</h3><span class="muted">{a["hours"]}h total learning + building</span></span><span class="meta"><span id="{a["id"]}-progress">0%</span><span class="chev">⌄</span></span></button><div class="mini-progress"><span id="{a["id"]}-fill"></span></div><div class="topic-body" id="body-{a["id"]}">{body}</div></article>'
 if a['id']=='sql':roadbody+='</div></div></section>'+poster('mha','GO BEYOND · PLUS ULTRA','“Go beyond. PLUS ULTRA!”','You can now retrieve and check data. Next: turn it into a dashboard that answers a real question. One validated measure is a bigger power-up than ten decorative visuals.')+'<section class="continued"><div class="container"><div class="topic-grid">'
roadbody+='</div>'
parts.append(section('roadmap','THE TRAINING ARC','Your 28-week roadmap.','Every season ends with evidence—not a watched-video badge. The weeks are sequential; small review and application habits run alongside them.',roadbody))
schedule='<div class="grid2"><div class="panel"><h3>Standard week · 12 hours</h3><ul><li><b>Four 90-minute blocks:</b> 6 hours of focused practice across shift days.</li><li><b>One 4-hour build block:</b> on your most suitable day off; include breaks.</li><li><b>Two 1-hour review blocks:</b> redo mistakes, explain a result, update your log.</li><li><b>One genuinely free day:</b> move blocks to protect rest.</li></ul><p style="margin-top:12px">Choose times after seeing your rota. A fixed 05:30 wake-up is not required.</p></div><div class="panel"><h3>Inside a 90-minute block</h3><ul><li>10 min: retrieve yesterday’s idea without notes.</li><li>20 min: one targeted lesson or documentation page.</li><li>50 min: build or solve independently.</li><li>10 min: check your output and record a mistake or insight.</li></ul><p style="margin-top:12px">Across the week, aim for roughly 70% doing/checking and 30% learning. This is a study rule, not a scientific guarantee.</p></div></div><div class="note"><b>Heavy rota / low-energy week:</b> use three 20-minute review sessions and one 60-minute build block (2 hours total). Do not pretend that equals 12 hours. Roll unfinished work forward and revise your finish date. On breaks, rest first; study only if it helps you.</div><div class="panel"><h3>The five laws of your training arc</h3><ol><li>Build from memory after the lesson.</li><li>One boss per season; fix the deliverable before adding tools.</li><li>Log evidence, not just hours.</li><li>Review mistakes in short repeatable sessions.</li><li>Protect sleep, planned rest and confidential data.</li></ol></div>'
parts.append(section('schedule','REAL-LIFE TRAINING','A schedule that survives Lidl shifts.','Keep the commitment flexible enough to repeat. The 12-hour budget includes projects, revision and job-search work—not extra homework on top.',schedule))
milestones=[('Week 1','Toolkit works, baseline tested, learning log started.'),('Week 4','Excel retail workbook refreshes and totals reconcile.'),('Week 8','30 SQL queries explained and one timed test completed.'),('Week 13','Power BI retail report + demo; first matched applications if ready.'),('Week 15','One-page decision brief with uncertainty and limitations.'),('Week 19','Reproducible pandas analysis + a report-generation script.'),('Week 23','Flagship local-data capstone; best three projects polished.'),('Week 25','Two SQL mocks, an Excel task and four STAR stories.'),('Week 28','A functioning application pipeline and next-step review—not a guaranteed offer.')]
parts.append(section('milestones','MILESTONE SAVE-POINTS','Look back. You are levelling up.','Advance when the evidence is ready; the week number is a planning guide.','<ul class="milestones">'+''.join(f'<li><b>{w}</b><span>{t}</span></li>' for w,t in milestones)+'</ul>'))
parts.append(poster('solo','BOSS RUSH · SOLO LEVELING','ARISE. Five projects. Five levels.','Clear one, unlock the next. Three polished case studies will lead your portfolio; two smaller projects show your fundamentals. Every one needs a question, checks and a useful conclusion.'))
projects=[('1','Week 4','Retail sales workbook','Excel · Power Query · PivotTables','Which products and trading periods drive revenue in this synthetic retail dataset?','https://www.kaggle.com/datasets/mashlyn/online-retail-ii-uci','Public Online Retail II dataset (check licence); or clearly labelled synthetic data',['Document raw/clean sheets, row counts and a data dictionary.','Create revenue and units summaries with slicers.','Check returns, missing customer IDs and duplicate rows explicitly.','Ship .xlsx, a one-page PDF and three findings.'],'Can you clean and reconcile a spreadsheet without hiding the messy parts?'),('2','Week 8','Retail SQL investigation','MySQL · SQL · GitHub','Which categories perform best, and how does performance change over time?','https://github.com/microsoft/sql-server-samples/tree/master/samples/databases/northwind-pubs','Northwind sample (SQL Server scripts; adapt schema for MySQL), or your own synthetic retail tables',['Use customers, orders, order lines and products with known keys.','Write 30 queries, including joins, CTEs and ranking windows.','Include failed assumptions and checks that caught duplicate joins.','Ship schema, loading instructions, queries and selected results.'],'Can you turn a question into a trustworthy query?'),('3','Week 13','Retail performance dashboard','Power BI · Star schema · DAX','What changed this month, and which category deserves attention?','https://www.kaggle.com/datasets/mashlyn/online-retail-ii-uci','Reuse public/synthetic retail data; do not present it as Lidl data',['Build a sales fact table with product and date dimensions.','Validate revenue and comparison measures against SQL.','Create two focused pages rather than ten cluttered ones.','Ship PBIX + screenshots/PDF + 3-minute demo; public sharing is optional.'],'Can you model data and explain a measure, not merely draw a chart?'),('4','Week 19','NHS waiting-time trend brief','Python · pandas · Matplotlib','How do selected published waiting-time measures vary over comparable periods?','https://www.england.nhs.uk/statistics/statistical-work-areas/rtt-waiting-times/','NHS England RTT published statistics; inspect definitions and available periods',['Select a small set of comparable published files and record metadata.','Handle missing/suppressed values without treating them as zero.','Generate clean data, summary tables and a readable trend chart.','Explain that aggregate waiting-time data cannot establish causes or individual outcomes.'],'Can you make a public-data analysis reproducible and cautious?'),('5','Weeks 20–23','East Sussex insight capstone','SQL · Power BI · Excel checks · optional pandas','How has one local indicator changed, and how does East Sussex compare with an appropriate benchmark?','https://data.eastsussex.gov.uk/','East Sussex in Figures; use ONS as an alternative source',['Choose a manageable indicator with stable geography and definitions.','Document extraction, cleaning, joins, grain and reconciliation.','Create a dashboard and one-page evidence-led briefing.','Ship code, README, sources, limitations and a five-minute walkthrough.'],'Can you own a complete analysis and defend its limitations?')]
projectbody='<div class="project-grid">'
for num,w,t,stack,q,u,src,items,why in projects:
 projectbody+=f'<article class="project-card"><div class="project-top"><span style="font-size:1rem;font-weight:850">LV.{num} · {w}</span></div><div class="project-body"><h4>{t}</h4><p><b>{stack}</b></p><p><b>Question:</b> {q}</p><p>{link(u,src)}</p><ul>'+''.join(f'<li>{i}</li>' for i in items)+f'</ul><div class="note"><b>Interview proof:</b> {why}</div></div></article>'
projectbody+='</div><div class="note"><b>Portfolio honesty:</b> project outcomes are not workplace achievements. Say “built a synthetic retail report with X validated measures”, not “saved Lidl £X”. Only claim time savings you actually measured in a real process.</div>'
parts.append(section('projects','THE PROJECT LADDER','Five levels. Real evidence.','These replace the PDF’s web-development apps with pure analytics deliverables. No API, React or full-stack requirement.',projectbody))
parts.append(poster('levi','ATTACK ON TITAN ARC','You don’t know the outcome. Apply anyway.','Use rejection as feedback, not a verdict. Keep your search matched to your skills, geography and eligibility—and keep improving the evidence you send.'))
jobbody='<div class="grid3"><div class="panel"><h3>1 · Eastbourne & East Sussex</h3><p>Search local public services, healthcare, education and operational reporting roles. Smaller geography means fewer suitable adverts; do not force a weekly quota with irrelevant applications.</p></div><div class="panel"><h3>2 · Brighton, Hove & Lewes</h3><p>Widen to nearby employers and hybrid teams. Check real door-to-door travel time, shift compatibility and the number of office days. Do not assume a 30-minute commute.</p></div><div class="panel"><h3>3 · Wider UK / remote</h3><p>Remote junior roles can be competitive. Read office attendance and residence requirements; “remote” does not necessarily mean work from anywhere. Consider London hybrid only if the commute and cost work.</p></div></div><div class="panel"><h3>Bookmark your search routes</h3><div class="pill-menu">'+''.join(link(u,t) for u,t in [('https://www.jobs.nhs.uk/','NHS Jobs'),('https://www.civilservicejobs.service.gov.uk/','Civil Service Jobs'),('https://www.reed.co.uk/jobs/junior-data-analyst-jobs-in-eastbourne','Reed'),('https://uk.indeed.com/jobs?q=junior+data+analyst&l=Eastbourne','Indeed'),('https://www.linkedin.com/jobs/search/?keywords=Junior%20Data%20Analyst&location=Eastbourne','LinkedIn'),('https://www.eastsussex.gov.uk/jobs','East Sussex County Council')])+'</div><p style="margin-top:15px">Alerts: <b>Junior Data Analyst · Reporting Analyst · MI Analyst · Information Analyst · BI Assistant · Data Quality Analyst.</b> Exclude Business Analyst roles unless the actual work is data analysis and interests you.</p></div>'
employers=[('East Sussex Healthcare NHS Trust','Eastbourne / Hastings','Information, performance and reporting teams','https://www.esht.nhs.uk/working-for-us/'),('East Sussex County Council','Lewes / county-wide','Performance, public-service data and reporting','https://www.eastsussex.gov.uk/jobs'),('University Hospitals Sussex NHS FT','Sussex sites','Information and operational reporting; check exact base','https://www.uhsussex.nhs.uk/careers/'),('Brighton & Hove City Council','Brighton / Hove','Data, insight and performance roles','https://www.brighton-hove.gov.uk/jobs'),('American Express','Brighton / UK','Operations and analytics; some roles need prior experience','https://www.americanexpress.com/en-us/careers/'),('Legal & General','Hove / UK','Reporting and financial-services analytics; check entry criteria','https://careers.legalandgeneral.com/'),('Bupa','Brighton / UK','Healthcare/insurance reporting and insight','https://careers.bupa.co.uk/'),('University of Sussex','Falmer','Planning, student data and reporting','https://www.sussex.ac.uk/about/jobs/')]
jobbody+='<h3 style="margin-top:26px">Starter target list · research leads, not confirmed openings</h3><div class="table-wrap"><table><thead><tr><th>Organisation</th><th>Area</th><th>Why investigate</th></tr></thead><tbody>'+''.join(f'<tr><td>{link(u,t)}</td><td>{a}</td><td>{w}</td></tr>' for t,a,w,u in employers)+'</tbody></table></div><p class="muted">Check current vacancies, office base and essential criteria on each official site. This list does not assert that any employer is currently hiring juniors.</p>'
jobbody+='<div class="grid2"><div class="panel"><h3>Application maths you control</h3><p>Starting target: <b>5 well-matched applications + 2 genuine networking messages per week</b>, when suitable vacancies exist. Four weeks at that rate is 20 applications—not a predicted number of interviews.</p><p style="margin-top:10px">After 15–20 matched submissions with no screening calls, review your CV, evidence, targeting and eligibility. If screens happen but tests fail, practise the failed skill. If interviews fail, review examples and communication.</p></div><div class="panel"><h3>Your tracker fields</h3><p>Date · employer · role · URL · salary · location/office days · essential criteria · eligibility · CV version · project used · stage · follow-up date · result · feedback.</p><p style="margin-top:10px">Read right-to-work and sponsorship conditions carefully. Your immigration status is not assumed in this plan. Never pay a recruiter a fee to secure an ordinary job.</p></div></div><div class="panel"><h3>A referral message you can make your own</h3><div class="codebox">Hi [Name], I work in retail at Lidl in Eastbourne and I’m building towards a junior data-analytics role.\n\nI’ve built [project + link] using [Excel / SQL / Power BI]. It answers [specific question], with [one verified finding or quality check].\n\nI saw [role + reference] at [company]. If you feel my work is a fit, would you be open to a short conversation or pointing me towards the right application route?\n\nThanks for your time,\n[Your name]</div></div><div class="panel"><h3>CV upgrades before your next application</h3><ul><li><b>Projects first:</b> question → tools → checks → actual result. Use numbers only when true.</li><li><b>Keep the stack visible:</b> Excel, SQL, Power BI; add Python when you can demonstrate it.</li><li><b>Transfer retail skills honestly:</b> prioritisation, accuracy, teamwork and customer communication. Do not invent volumes, savings or analytical duties.</li><li><b>Use a clean one- or two-page UK CV:</b> no photo, skill bars or decorative columns. Tailor length to useful evidence.</li><li><b>Clickable links:</b> GitHub, flagship case study and demo. Check them while logged out.</li><li><b>Current employment wording:</b> do not say “ex-Lidl” unless you have left.</li></ul></div>'
parts.append(section('jobhunt','ENDGAME','The Eastbourne job-hunt playbook.','Where to look, how to widen your search and what to send. Start small when your work is ready; keep the routine sustainable.',jobbody))
questions={
'SQL · 10 questions':[
('What is the difference between WHERE and HAVING?','WHERE filters rows before aggregation; HAVING filters grouped results. Show a total-sales example.'),('What is the difference between INNER and LEFT JOIN?','Explain which rows are preserved, unmatched NULLs and the importance of the join key.'),('Why did revenue double after a join?','Check the grain and key uniqueness. A one-to-many join can duplicate fact rows; aggregate or fix the key, do not hide it with DISTINCT.'),('What is the difference between COUNT(*), COUNT(column) and COUNT(DISTINCT column)?','All rows, non-NULL values and distinct non-NULL values respectively.'),('How would you get the top three products per category?','Aggregate to product/category grain, then use ROW_NUMBER or DENSE_RANK depending on the tie policy.'),('How do you find customers with no orders?','LEFT JOIN + unmatched-key IS NULL, or NOT EXISTS; explain NULL risks with NOT IN.'),('When would you use a CTE?','To express logical steps clearly. It is not automatically a performance improvement.'),('How would you calculate month-on-month change?','Aggregate by month, use LAG and divide the difference by the prior value with zero handling. Consider absent months.'),('How do you handle missing values?','Decide what NULL means, use IS NULL and only COALESCE when the replacement is semantically justified.'),('How would you validate your result?','Check row counts, grain, key uniqueness, totals, sampled cases and an independent calculation.')],
'Excel & data quality · 10 questions':[
('When would you use XLOOKUP rather than a PivotTable?','A lookup returns related values by key; a pivot summarises data. Check key uniqueness and the desired grain.'),('How would you clean a messy CSV?','Preserve raw data, inspect types, dates, blanks and duplicates, then document and reconcile each transformation.'),('What is a repeatable Power Query workflow?','Typed import → cleaning steps → merge/unpivot → validation → refreshable output. Test on a replacement file.'),('What is the difference between a blank and zero?','A blank may be unknown or not applicable; zero is an observed value. They can change counts and averages differently.'),('How do SUMIFS and COUNTIFS help?','They aggregate by multiple criteria. Explain a date-bounded category-sales example.'),('How do you check a lookup is correct?','Use exact matching, inspect unmatched values, test duplicates and sample returned records.'),('How would you build a manager’s weekly report?','Clarify decision, definitions and audience; automate import, reconcile totals, then present a small number of useful KPIs.'),('What is percentage-point change?','A rate moving from 10% to 12% rises by 2 percentage points or 20% relative—not 2% relative.'),('Why might Excel show dates incorrectly?','Locale, mixed text/date types or serial formatting; parse deliberately and inspect ambiguous dates.'),('What would you do if two reports disagree?','Compare sources, refresh times, grain, filters, date boundaries and definitions before deciding which is wrong.')],
'Power BI, statistics & Python · 10 questions':[
('Why use a star schema?','Clear fact/dimension grain, predictable relationships and reusable measures; explain your own model.'),('What is the difference between a measure and a calculated column?','A measure evaluates at query time in filter context; a column is computed per row and stored during refresh.'),('What does CALCULATE do?','Evaluates an expression in modified filter context. Demonstrate using a measure from your project.'),('How would you test a dashboard?','Reconcile KPIs, test slicers and relationships, inspect blanks, zero denominators, dates and accessibility.'),('When is median more useful than mean?','Often when a distribution is skewed or affected by outliers; explain both with a simple example.'),('Does correlation prove causation?','No. Confounding, selection bias and reverse causality may explain an association.'),('How do you explain uncertainty to a manager?','Describe the range, assumptions, sample/data limits and what additional evidence would change the decision.'),('How would you validate a pandas merge?','Inspect key uniqueness, use validate= where appropriate, track unmatched rows and reconcile totals and counts.'),('How do you make a notebook reproducible?','Record source versions and dependencies, use clear relative paths and re-run from a fresh environment in order.'),('Should you use Publish to web for a company report?','No for confidential data: it makes content publicly accessible. Use approved sharing, access controls and licensing.')],
'Career change & behavioural · 10 questions':[
('Why move from Lidl into analytics?','Use a truthful past → interest → concrete learning evidence → role-fit story. Avoid criticising retail work.'),('Tell me about an error you caught.','Use a real STAR example: what you checked, what you did and what actually happened. No invented savings.'),('How do you prioritise competing tasks?','Clarify urgency, impact, dependencies and stakeholder expectations. Use a genuine shift or project example.'),('Tell me about working with a difficult customer.','Show listening, clarity, boundaries, appropriate escalation and a factual outcome.'),('Describe a time you worked in a team.','Be specific about your contribution and recognise others; do not claim the whole team’s result as yours.'),('How do you explain technical work to non-technical people?','Start with the decision and meaning, use one clear visual, define units and check understanding.'),('What if a manager requests a misleading chart?','Explain the risk respectfully, show an honest alternative and document or escalate if needed.'),('What would you do with sensitive customer data?','Use only authorised access and purpose, minimise exposure, follow policy and ask the appropriate data owner if uncertain.'),('What is a weakness you are improving?','Choose a genuine manageable gap and give a concrete practice plan with evidence of progress.'),('What would you ask us?','Ask about the team’s data quality problems, first-90-day expectations, code/report review and support for junior analysts.')]
}
