resources=[('https://support.microsoft.com/en-us/office/keyboard-shortcuts-in-excel-1798d9d5-842a-42b8-9c99-9b7213f0040f','Excel keyboard shortcuts','Web · Microsoft','Daily spreadsheet work; check platform-specific keys.'),('https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-accessibility-keyboard-shortcuts','Power BI shortcuts','Web · Microsoft','Navigation and authoring; Desktop and Service can differ.'),('https://learn.microsoft.com/en-us/dax/','DAX reference','Web · Microsoft','Check function behaviour and examples.'),('https://www.postgresql.org/docs/current/tutorial-sql.html','SQL tutorial/reference','Web · PostgreSQL','Useful reference; syntax can differ from the MySQL course.'),('https://pandas.pydata.org/Pandas_Cheat_Sheet.pdf','pandas cheat sheet','PDF · pandas','DataFrame operations and quick reminders.'),('https://training.github.com/downloads/github-git-cheat-sheet.pdf','Git cheat sheet','PDF · GitHub','Version-control commands without a full Git course.'),('https://www.markdownguide.org/cheat-sheet/','Markdown cheat sheet','Web','Write clear project READMEs.'),('https://learn.microsoft.com/en-us/credentials/certifications/power-bi-data-analyst-associate/','PL-300 certification','Web · Microsoft','Optional after hands-on practice; check current fees and requirements.')]
cheat='<div class="table-wrap"><table><thead><tr><th>Resource</th><th>Type</th><th>Why use it</th></tr></thead><tbody>'+''.join(f'<tr><td>{link(u,t)}</td><td>{typ}</td><td>{why}</td></tr>' for u,t,typ,why in resources)+'</tbody></table></div><div class="grid2"><div class="panel"><h3>Excel · daily shortcuts (Windows)</h3><div class="codebox">Ctrl + T       Format as Table\nCtrl + Shift + L  Toggle filters\nAlt + =        AutoSum\nCtrl + 1       Format Cells\nCtrl + Arrow   Jump to data edge\nCtrl + Shift + Arrow  Select to edge\nF4             Cycle absolute references (in formula)\nCtrl + `       Show formulas\nCtrl + ;       Insert today’s date\nCtrl + Alt + F5 Refresh all connections\nAlt, N, V      Insert PivotTable (ribbon sequence)\nCtrl + Z       Undo</div><p>Some laptop keys require Fn; Mac and web shortcuts differ.</p></div><div class="panel"><h3>SQL · patterns worth remembering</h3><div class="codebox">SELECT category, SUM(revenue) AS sales\nFROM sales\nWHERE sale_date &gt;= \'2026-01-01\'\n  AND sale_date &lt; \'2026-02-01\'\nGROUP BY category\nHAVING SUM(revenue) &gt; 1000\nORDER BY sales DESC;\n\n-- Never hide a broken join with DISTINCT.\n-- Check keys, grain and totals first.\n-- SQL dialects differ: verify date functions.</div></div><div class="panel"><h3>pandas · reliable habits</h3><div class="codebox">df = pd.read_csv("data.csv")\ndf.info()\ndf.isna().sum()\ndf.duplicated().sum()\n\n# Validate the expected key relationship:\nout = sales.merge(products, on="product_id",\n                  how="left", validate="many_to_one")\nassert len(out) == len(sales)\nsummary = out.groupby("category")["revenue"].sum()</div></div><div class="panel"><h3>Git · the safe daily loop</h3><div class="codebox">git status\ngit diff\ngit add analysis.sql README.md\ngit commit -m "Add checked monthly sales analysis"\ngit pull --rebase\ngit push\ngit log --oneline\n\n# Do not commit credentials or private data.\n# Inspect before staging; avoid blind reset --hard.</div></div></div><div class="note"><b>Metric reminder:</b> percentage change = (new − old) / old. If old = 0, define an explicit policy instead of forcing a percentage. In DAX, DIVIDE handles zero/blank denominators more safely than raw division.</div>'
