js='''
const STORE='eastbourneAnalyst_v4';
const legacyMap=LEGACY_MAP;
let storageWarned=false,toastTimer;
function showToast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function boxes(){return [...document.querySelectorAll('.checklist input[type=checkbox]')]}
function saveState(){const state={version:4,ticks:Object.fromEntries(boxes().map(b=>[b.dataset.key,b.checked]))};try{localStorage.setItem(STORE,JSON.stringify(state))}catch(e){if(!storageWarned){showToast('Storage blocked: export progress to keep your ticks.');storageWarned=true}}return state}
function updateProgress(save=true){const all=boxes(),done=all.filter(b=>b.checked).length,total=all.length,pct=Math.round(done/total*100);const rank=pct===100?'S-Rank':pct>=75?'A-Rank':pct>=50?'B-Rank':pct>=25?'C-Rank':'E-Rank';document.getElementById('heroPct').textContent=pct+'%';document.getElementById('heroPct2').textContent=pct+'%';document.getElementById('overallProgress').textContent=pct+'%';document.getElementById('heroCount').textContent=done+' / '+total+' checkpoints · '+rank;document.getElementById('footerProgress').textContent=pct+'% complete · '+rank;['progressBar','heroFill'].forEach(id=>document.getElementById(id).style.width=pct+'%');all.forEach(b=>b.closest('label').classList.toggle('done',b.checked));document.querySelectorAll('.checklist').forEach(list=>{const bs=[...list.querySelectorAll('input')],n=bs.filter(b=>b.checked).length,id=list.dataset.topic;document.getElementById(id+'-progress').textContent=n+'/'+bs.length+' · '+Math.round(n/bs.length*100)+'%';document.getElementById(id+'-fill').style.width=(n/bs.length*100)+'%'});if(save)saveState()}
function loadProgress(){try{const data=JSON.parse(localStorage.getItem(STORE)||'null');if(data&&data.ticks){boxes().forEach(b=>b.checked=data.ticks[b.dataset.key]===true)}else{const old=JSON.parse(localStorage.getItem('lidlAnalystProgress_v3')||'{}');Object.entries(legacyMap).forEach(([index,key])=>{if(old[index]){const b=boxes().find(b=>b.dataset.key===key);if(b)b.checked=true}})}}catch(e){showToast('Progress could not be loaded. You can import a backup.')}updateProgress(false)}
function toggleArc(button){const card=button.closest('.topic-card');card.classList.toggle('open');button.setAttribute('aria-expanded',String(card.classList.contains('open')))}
function expandAll(){document.querySelectorAll('.topic-card').forEach(c=>{c.classList.add('open');c.querySelector('button').setAttribute('aria-expanded','true')})}
function collapseAll(){document.querySelectorAll('.topic-card').forEach(c=>{c.classList.remove('open');c.querySelector('button').setAttribute('aria-expanded','false')})}
function resetProgress(){if(confirm('Reset all checkpoints? Export a backup first if you may want to restore them.')){boxes().forEach(b=>b.checked=false);updateProgress();showToast('Progress reset')}}
function exportProgress(){const state=saveState();state.exportedAt=new Date().toISOString();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Eastbourne_Analyst_Progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
document.getElementById('importFile').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;const data=JSON.parse(await f.text());if(data.version!==4||!data.ticks||typeof data.ticks!=='object')throw new Error('Invalid backup');if(!confirm('Replace current ticks with this backup?'))return;boxes().forEach(b=>b.checked=data.ticks[b.dataset.key]===true);updateProgress();showToast('Progress restored')}catch(err){showToast('Not a compatible progress backup.')}finally{e.target.value=''}});
boxes().forEach(b=>b.addEventListener('change',()=>{updateProgress();showToast(b.checked?'Saved · one level stronger.':'Checkpoint unchecked.')}));
document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',()=>{const id=a.getAttribute('href').slice(1),target=document.getElementById(id);if(target&&target.classList.contains('topic-card')){target.classList.add('open');target.querySelector('button').setAttribute('aria-expanded','true')}}));
let printState=null;
function openForPrint(){if(printState)return;printState={arcs:[...document.querySelectorAll('.topic-card')].map(c=>c.classList.contains('open')),details:[...document.querySelectorAll('details')].map(d=>d.open)};expandAll();document.querySelectorAll('details').forEach(d=>d.open=true)}
function restoreAfterPrint(){if(!printState)return;document.querySelectorAll('.topic-card').forEach((c,i)=>{c.classList.toggle('open',printState.arcs[i]);c.querySelector('button').setAttribute('aria-expanded',String(printState.arcs[i]))});document.querySelectorAll('details').forEach((d,i)=>d.open=printState.details[i]);printState=null}
function printRoadmap(){openForPrint();window.print()}
window.addEventListener('beforeprint',openForPrint);window.addEventListener('afterprint',restoreAfterPrint);
loadProgress();
'''.replace('LEGACY_MAP',json.dumps(legacy))
